import{n as e}from"./createLucideIcon-DLmAVpDi.js";import{St as t,u as n}from"./index-CCOe1rrM.js";import{t as r}from"./PdfPageWorkspace-BC4xbP_V.js";var i=e(),a=n(`extract-pdf-pages`),o={intro:`Extract Pages pulls specific pages out of a PDF and combines just those into a brand-new document, without touching the rest of the file.`,whyItMatters:`Often you only need a handful of pages from a longer PDF — a couple of relevant pages from a textbook chapter or a subset of a scanned form — rather than the whole thing.`,howItWorks:[`Select a PDF file — every page starts selected by default.`,`Click any page you don’t want to deselect it, leaving only the pages you want to keep marked.`,`Export the selected pages as a new PDF, in their original page order.`],examples:[{title:`Pulling relevant pages`,body:`Open a 40-page lecture PDF, deselect everything except the 3 pages covering one topic, and export just those to share separately.`},{title:`Removing most of a document`,body:`To strip a large PDF down to just a title page and a summary, deselect only those two and export \\u2014 since every page starts selected, keeping a small set means deselecting the majority rather than selecting from scratch.`}],mistakes:[`Using Split PDF when you only need a few pages together — Extract Pages gives you one combined file instead of a ZIP of every page.`,`Forgetting that every page starts selected — if you only want a couple of pages, you need to deselect the rest rather than click to select from a blank slate.`],tips:[`Double-check page numbers against the original before extracting — page numbering can shift if the PDF has unnumbered cover pages.`,`Since everything starts selected, extracting most of a document (removing just a few pages) is usually faster than extracting a small handful.`],faqs:[{question:`What’s the difference between this and Split PDF?`,answer:`Split PDF breaks every page into its own file; Extract Pages lets you choose specific pages and combines just those into one new document.`},{question:`Does the original PDF get modified?`,answer:`No — the original file stays untouched. Extract Pages creates a new document from your selection.`},{question:`What order do the extracted pages come out in?`,answer:`Always their original order in the source document, regardless of the order you clicked them in — not a custom order based on your selection sequence.`}],related:[{label:`Split PDF`,href:`/document-tools/split-pdf`},{label:`Delete Pages`,href:`/document-tools/delete-pdf-pages`},{label:`Merge PDF`,href:`/document-tools/merge-pdf`}]};function s(){return(0,i.jsx)(r,{mode:`extract`,toolName:a.name,tagline:a.tagline,description:a.description,path:`/document-tools/extract-pdf-pages`,icon:t,breadcrumb:{label:`Extract Pages`},toolSlug:a.slug,article:o})}export{s as default};